 style.textContent+="\n\n/* AUREL_LOGIN_MULTI_TONE_V4: login shell visual refinements only. */\n/* Borderless outer shell; retain the exact card geometry and all controls. */\n#aurel-auth-wall .auth-card{\n border:0!important;\n outline:none!important;\n background:transparent;\n border-radius:25px;\n overflow:hidden;\n box-shadow:0 26px 82px rgba(4,20,36,.3),0 5px 18px rgba(4,25,39,.12)!important;\n}\n/* Multi-tone ocean/indigo palette, instead of one flat block. */\n#aurel-auth-wall .auth-showcase{\n border:0!important;\n background:\n  radial-gradient(ellipse 74% 52% at 3% 4%,rgba(66,168,184,.38),transparent 80%),\n  radial-gradient(ellipse 86% 62% at 99% 9%,rgba(45,110,185,.26),transparent 75%),\n  radial-gradient(ellipse 77% 60% at 18% 100%,rgba(32,145,145,.35),transparent 75%),\n  linear-gradient(151deg,#10354e 0%,#174863 38%,#123750 70%,#163b59 100%)!important;\n}\n#aurel-auth-wall .auth-showcase::before{\n opacity:.11;\n background-image:linear-gradient(125deg,rgba(255,255,255,.2) 1px,transparent 1px),linear-gradient(35deg,rgba(255,255,255,.15) 1px,transparent 1px);\n background-size:66px 66px;\n mask-image:linear-gradient(180deg,transparent 3%,#000 85%);\n}\n#aurel-auth-wall .auth-showcase-head{z-index:2}\n#aurel-auth-wall .auth-showcase-kicker{color:#dcf5f7;letter-spacing:.16em}\n#aurel-auth-wall .auth-showcase-kicker::before{\n background:#6be7d3;\n box-shadow:0 0 0 4px rgba(107,231,211,.14),0 0 13px rgba(107,231,211,.37);\n}\n#aurel-auth-wall .auth-showcase h3{color:#fff;text-shadow:0 2px 12px rgba(2,30,47,.15)}\n#aurel-auth-wall .auth-showcase-copy{color:#d5eaf2}\n#aurel-auth-wall .auth-city-stage{\n border:0!important;\n border-radius:20px;\n box-shadow:0 15px 38px rgba(4,19,36,.29)!important;\n}\n#aurel-auth-wall .auth-city-video{opacity:1!important;filter:none!important}\n/* Light panel has individual pearl/sky/mint/lavender accents; remain readable. */\n#aurel-auth-wall .auth-form-panel{\n border-left:0!important;\n overflow:hidden;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-form-panel{\n background:\n  radial-gradient(ellipse 68% 48% at 100% 0%,rgba(155,217,238,.34),transparent 76%),\n  radial-gradient(ellipse 84% 66% at 0% 98%,rgba(165,227,218,.27),transparent 78%),\n  radial-gradient(ellipse 54% 45% at 102% 76%,rgba(193,194,240,.25),transparent 78%),\n  linear-gradient(145deg,#fcfefe 0%,#f5fbff 40%,#f1f8fc 77%,#f7f9ff 100%)!important;\n}\n#aurel-auth-wall .auth-form-panel::before{display:none!important}\n#aurel-auth-wall .auth-brandbar{\n border-bottom:1px solid rgba(56,135,170,.14);\n padding-bottom:22px;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-brand{\n background:linear-gradient(105deg,#123a55 8%,#216487 50%,#137c8e 100%);\n -webkit-background-clip:text;\n background-clip:text;\n -webkit-text-fill-color:transparent;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-subbrand{color:#638ba5}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-secure-tag{\n border:1px solid rgba(86,166,192,.22);\n background:linear-gradient(115deg,rgba(233,250,248,.93),rgba(230,244,255,.9))!important;\n color:#2f6681;\n box-shadow:0 4px 15px rgba(35,115,153,.07);\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-title{\n color:#17384e;\n}\n#aurel-auth-wall .auth-title{\n border-left:4px solid #36b9b5;\n padding-left:13px;\n margin-left:-17px;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-description{color:#68849a}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-label{color:#2f5168}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-field input{\n background:rgba(255,255,255,.92)!important;\n border:1px solid rgba(135,180,204,.42);\n box-shadow:0 6px 17px rgba(18,89,125,.045),inset 0 1px 0 rgba(255,255,255,.95);\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-field input:focus{\n border-color:#27a9b8!important;\n box-shadow:0 0 0 3px rgba(40,176,185,.16),0 9px 21px rgba(24,93,138,.07);\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-password-toggle:hover{\n color:#186d88;background:rgba(52,173,185,.1);\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-submit{\n background:linear-gradient(108deg,#154e73 0%,#1b7298 53%,#14878c 100%)!important;\n border:0!important;\n box-shadow:0 11px 25px rgba(16,93,123,.19)!important;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-submit:hover:not(:disabled){\n background:linear-gradient(108deg,#176088,#2186a4 52%,#189a99 100%)!important;\n box-shadow:0 14px 29px rgba(16,93,123,.24)!important;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-alternate{color:#087f99}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-alternate:hover{color:#095b7b}\nbody.aurel-dark-theme #aurel-auth-wall .auth-form-panel{\n background:\n  radial-gradient(ellipse at 94% 8%,rgba(48,118,148,.20),transparent 65%),\n  radial-gradient(ellipse at 5% 100%,rgba(37,108,104,.18),transparent 68%),\n  linear-gradient(142deg,#15283b 0%,#102232 52%,#142536 100%)!important;\n}\nbody.aurel-dark-theme #aurel-auth-wall .auth-title{border-left-color:#49c3c0}\n@media(max-width:830px){\n #aurel-auth-wall .auth-card{border:0!important}\n #aurel-auth-wall .auth-form-panel{border-top:0!important}\n #aurel-auth-wall .auth-title{margin-left:-13px;padding-left:10px;border-left-width:3px}\n}\n@media(max-width:530px){\n #aurel-auth-wall .auth-card{border-radius:20px}\n #aurel-auth-wall .auth-showcase{border:0!important}\n #aurel-auth-wall .auth-form-panel{border:0!important}\n}\n";
 style.textContent+="\n\n/* AUREL_AUTH_EDGE_TO_EDGE_V5 - replaces centered dialog layout, ONLY inside login overlay */\n/* Entire browser viewport is the two-panel login page; no border, card or surrounding cover. */\n#aurel-auth-wall{\n display:block!important;\n padding:0!important;\n margin:0!important;\n width:100%!important;\n min-height:100dvh;\n height:100dvh;\n overflow-x:hidden!important;\n overflow-y:auto!important;\n background:#eaf4f9!important;\n}\n#aurel-auth-wall:before,#aurel-auth-wall::before{display:none!important}\n#aurel-auth-wall .auth-card{\n width:100%!important;\n max-width:none!important;\n height:100dvh!important;\n min-height:100dvh!important;\n margin:0!important;\n padding:0!important;\n display:grid!important;\n grid-template-columns:minmax(0,1fr) minmax(0,1fr)!important;\n border:0!important;\n border-radius:0!important;\n outline:0!important;\n overflow:hidden!important;\n background:transparent!important;\n box-shadow:none!important;\n transform:none;\n}\n#aurel-auth-wall .auth-showcase{\n position:relative!important;\n min-width:0!important;\n min-height:100dvh!important;\n height:100dvh!important;\n display:flex!important;\n flex-direction:column!important;\n justify-content:flex-start!important;\n padding:clamp(32px,5.3vw,80px)!important;\n margin:0!important;\n border:0!important;\n border-radius:0!important;\n background:#0a3146!important;\n overflow:hidden!important;\n isolation:isolate;\n}\n#aurel-auth-wall .auth-showcase::before{\n display:none!important;\n}\n#aurel-auth-wall .auth-city-stage{\n position:absolute!important;\n inset:0!important;\n top:0!important;\n right:0!important;\n bottom:0!important;\n left:0!important;\n width:100%!important;\n height:100%!important;\n min-height:0!important;\n margin:0!important;\n padding:0!important;\n border:0!important;\n border-radius:0!important;\n box-shadow:none!important;\n background:#0a3146!important;\n opacity:1!important;\n transform:none!important;\n z-index:0!important;\n overflow:hidden!important;\n}\n#aurel-auth-wall .auth-city-video{\n width:100%!important;\n height:100%!important;\n object-fit:cover!important;\n object-position:center center!important;\n opacity:1!important;\n filter:none!important;\n transform:none!important;\n}\n#aurel-auth-wall .auth-city-stage::before{\n display:block!important;\n content:\"\"!important;\n inset:0!important;\n position:absolute!important;\n background:linear-gradient(180deg,rgba(4,23,36,.74) 0%,rgba(5,23,38,.21) 34%,rgba(3,19,31,.04) 49%,rgba(3,20,33,.65) 100%)!important;\n z-index:1!important;\n}\n#aurel-auth-wall .auth-city-stage::after{display:none!important}\n#aurel-auth-wall .auth-city-grid,#aurel-auth-wall .auth-city-edge{display:none!important}\n#aurel-auth-wall .auth-showcase-head{\n position:relative!important;\n z-index:3!important;\n width:min(100%,510px);\n padding:0!important;\n margin:0!important;\n text-shadow:0 2px 18px rgba(0,16,29,.38);\n}\n#aurel-auth-wall .auth-showcase-kicker{\n font-size:11px!important;\n letter-spacing:.18em!important;\n color:#dcfaf9!important;\n}\n#aurel-auth-wall .auth-showcase h3{\n max-width:490px!important;\n margin:27px 0 14px!important;\n font-size:clamp(30px,3.3vw,52px)!important;\n line-height:1.13!important;\n letter-spacing:-.042em!important;\n font-weight:830!important;\n color:#fff!important;\n text-shadow:0 2px 20px rgba(0,17,28,.4)!important;\n}\n#aurel-auth-wall .auth-showcase-copy{\n max-width:390px!important;\n font-size:clamp(12px,1vw,15px)!important;\n line-height:1.75!important;\n color:#e2f0f7!important;\n text-shadow:0 1px 10px rgba(0,17,27,.68);\n}\n#aurel-auth-wall .auth-city-glass{\n display:block!important;\n position:absolute!important;\n z-index:3!important;\n left:clamp(32px,5.3vw,80px)!important;\n right:clamp(32px,5.3vw,80px)!important;\n bottom:clamp(38px,6vh,76px)!important;\n width:auto!important;\n max-width:540px!important;\n padding:0!important;\n margin:0!important;\n border:0!important;\n border-radius:0!important;\n background:transparent!important;\n backdrop-filter:none!important;\n -webkit-backdrop-filter:none!important;\n box-shadow:none!important;\n}\n#aurel-auth-wall .auth-glass-header{\n margin-bottom:14px!important;\n}\n#aurel-auth-wall .auth-glass-header span{\n font-size:11px!important;\n color:#9beadf!important;\n letter-spacing:.21em!important;\n}\n#aurel-auth-wall .auth-glass-title{\n max-width:495px;\n font-size:clamp(21px,2.3vw,35px)!important;\n line-height:1.22!important;\n font-weight:840!important;\n color:#fff!important;\n letter-spacing:-.04em;\n text-shadow:0 2px 17px rgba(0,10,18,.9)!important;\n}\n#aurel-auth-wall .auth-glass-caption{\n max-width:370px!important;\n margin-top:13px!important;\n font-size:13px!important;\n line-height:1.68!important;\n color:#edf6fa!important;\n text-shadow:0 1px 10px rgba(0,10,18,.92)!important;\n}\n#aurel-auth-wall .auth-glass-tags{margin-top:23px!important;gap:9px!important}\n#aurel-auth-wall .auth-glass-tags span{\n padding:8px 13px!important;\n border-radius:999px!important;\n color:#f0fdff!important;\n font-size:11px!important;\n background:rgba(7,41,56,.44)!important;\n border:1px solid rgba(211,245,254,.34)!important;\n}\n/* The actual sign-in area uses full height, but contents remain elegantly centered. */\n#aurel-auth-wall .auth-form-panel{\n min-width:0!important;\n height:100dvh!important;\n min-height:100dvh!important;\n margin:0!important;\n padding:clamp(28px,5.4vw,90px)!important;\n border:0!important;\n border-radius:0!important;\n display:flex!important;\n flex-direction:column!important;\n align-items:center!important;\n justify-content:safe center!important;\n overflow-y:auto!important;\n isolation:isolate;\n}\nbody:not(.aurel-dark-theme) #aurel-auth-wall .auth-form-panel{\n background:\n  radial-gradient(ellipse 74% 53% at 100% 0%,rgba(154,212,229,.32),transparent 74%),\n  radial-gradient(ellipse 72% 48% at 0% 100%,rgba(154,230,211,.23),transparent 72%),\n  linear-gradient(140deg,#fff 0%,#f7fbfd 53%,#f1f8fc 100%)!important;\n}\n#aurel-auth-wall .auth-form-panel::before{display:none!important}\n#aurel-auth-wall .auth-form-panel > *{\n width:100%;\n max-width:480px;\n flex-shrink:0;\n}\n#aurel-auth-wall .auth-brandbar{padding-bottom:25px!important}\n#aurel-auth-wall .auth-brand{font-size:34px!important}\n#aurel-auth-wall .auth-title{\n margin:33px 0 11px!important;\n padding-left:15px!important;\n border-left:3px solid #36b9b5!important;\n font-size:clamp(26px,2.3vw,34px)!important;\n}\n#aurel-auth-wall .auth-description{\n max-width:480px!important;\n margin:0 0 28px!important;\n font-size:14px!important;\n line-height:1.75!important;\n}\n#aurel-auth-wall .auth-field input{height:56px!important;font-size:14px!important;border-radius:14px!important}\n#aurel-auth-wall .auth-label{font-size:13px!important}\n#aurel-auth-wall .auth-field{margin-bottom:18px!important}\n#aurel-auth-wall .auth-submit{min-height:56px!important;font-size:15px!important;border-radius:14px!important}\n#aurel-auth-wall .auth-switch{margin-top:20px!important}\nbody.aurel-dark-theme #aurel-auth-wall .auth-form-panel{\n background:\n  radial-gradient(circle at 100% 0%,rgba(42,112,140,.22),transparent 55%),\n  linear-gradient(135deg,#15283b,#0e1e30)!important;\n}\n/* Tablet and phone: a panoramic banner above the form, with no detached margins. */\n@media(max-width:960px){\n #aurel-auth-wall{height:auto!important;min-height:100dvh}\n #aurel-auth-wall .auth-card{\n  display:flex!important;\n  flex-direction:column!important;\n  grid-template-columns:none!important;\n  min-height:100dvh!important;\n  height:auto!important;\n  overflow:visible!important;\n }\n #aurel-auth-wall .auth-showcase{\n  width:100%!important;\n  flex:0 0 auto!important;\n  height:clamp(212px,30dvh,275px)!important;\n  min-height:0!important;\n  padding:26px 30px!important;\n }\n #aurel-auth-wall .auth-showcase-head{z-index:3!important}\n #aurel-auth-wall .auth-showcase h3{\n  max-width:290px!important;\n  margin:11px 0 7px!important;\n  font-size:23px!important;\n  line-height:1.22!important;\n }\n #aurel-auth-wall .auth-showcase-copy{\n  max-width:270px!important;\n  font-size:11px!important;\n  line-height:1.5!important;\n }\n #aurel-auth-wall .auth-city-stage{\n  position:absolute!important;\n  inset:0!important;\n  width:100%!important;\n  height:100%!important;\n  min-height:0!important;\n  opacity:1!important;\n  transform:none!important;\n }\n #aurel-auth-wall .auth-city-stage::before{\n  background:linear-gradient(90deg,rgba(2,25,41,.84) 0%,rgba(5,31,48,.46) 55%,rgba(5,30,48,.24) 100%)!important;\n }\n #aurel-auth-wall .auth-city-glass{display:none!important}\n #aurel-auth-wall .auth-form-panel{\n  min-height:calc(100dvh - 245px)!important;\n  height:auto!important;\n  width:100%!important;\n  overflow:visible!important;\n  padding:clamp(28px,6vw,55px)!important;\n }\n #aurel-auth-wall .auth-form-panel > *{max-width:520px}\n #aurel-auth-wall .auth-title{margin:25px 0 11px!important}\n #aurel-auth-wall .auth-description{margin-bottom:23px!important}\n}\n@media(max-width:530px){\n #aurel-auth-wall .auth-showcase{\n  height:205px!important;\n  padding:24px!important;\n }\n #aurel-auth-wall .auth-showcase-kicker{font-size:9px!important}\n #aurel-auth-wall .auth-showcase h3{\n  font-size:20px!important;\n  margin:12px 0 7px!important;\n }\n #aurel-auth-wall .auth-showcase-copy{font-size:10px!important;max-width:245px!important}\n #aurel-auth-wall .auth-form-panel{\n  min-height:calc(100dvh - 205px)!important;\n  padding:29px 25px 32px!important;\n }\n #aurel-auth-wall .auth-brand{font-size:27px!important}\n #aurel-auth-wall .auth-secure-tag{font-size:8px!important;padding:7px 8px!important}\n #aurel-auth-wall .auth-title{font-size:25px!important;margin:24px 0 9px!important}\n #aurel-auth-wall .auth-description{font-size:12px!important;margin-bottom:18px!important}\n #aurel-auth-wall .auth-field input{height:51px!important}\n #aurel-auth-wall .auth-submit{min-height:52px!important}\n}\n@media(max-width:375px){\n #aurel-auth-wall .auth-showcase{height:185px!important}\n #aurel-auth-wall .auth-form-panel{padding:23px 19px 27px!important}\n}\n@media(min-width:961px) and (max-height:670px){\n #aurel-auth-wall .auth-showcase{padding:30px 50px!important}\n #aurel-auth-wall .auth-showcase h3{font-size:29px!important;margin:16px 0 8px!important}\n #aurel-auth-wall .auth-city-glass{left:50px!important;right:50px!important;bottom:27px!important}\n #aurel-auth-wall .auth-glass-title{font-size:22px!important}\n #aurel-auth-wall .auth-glass-tags{margin-top:13px!important}\n #aurel-auth-wall .auth-form-panel{padding:22px 50px!important}\n #aurel-auth-wall .auth-title{margin:17px 0 8px!important;font-size:24px!important}\n #aurel-auth-wall .auth-description{margin-bottom:13px!important}\n #aurel-auth-wall .auth-field{margin-bottom:12px!important}\n #aurel-auth-wall .auth-field input{height:48px!important}\n #aurel-auth-wall .auth-submit{min-height:49px!important;margin-top:11px!important}\n}\n";
 style.textContent+="\n\n/* AUREL_LOGIN_VIDEO_CLARITY_V6: clear city video + no decorative line. */\n#aurel-auth-wall .auth-glass-header svg { display:none!important; }\n#aurel-auth-wall .auth-city-video {\n  filter:contrast(1.055) saturate(1.045) brightness(1.025)!important;\n  opacity:1!important;\n  transform:none!important;\n  image-rendering:auto;\n}\n#aurel-auth-wall .auth-city-stage::before {\n  background:linear-gradient(180deg,\n    rgba(4,23,36,.34) 0%,\n    rgba(5,23,38,.10) 28%,\n    rgba(3,19,31,0) 53%,\n    rgba(3,20,33,.30) 100%)!important;\n}\n#aurel-auth-wall .auth-glass-title,\n#aurel-auth-wall .auth-glass-caption,\n#aurel-auth-wall .auth-showcase h3,\n#aurel-auth-wall .auth-showcase-copy {\n  text-shadow:0 2px 12px rgba(0,9,19,.8),0 1px 3px rgba(0,9,19,.85)!important;\n}\n@media(max-width:960px) {\n  #aurel-auth-wall .auth-city-stage::before{\n    background:linear-gradient(90deg,rgba(2,25,41,.41) 0%,rgba(5,31,48,.07) 75%,transparent 100%)!important;\n  }\n}\n";
 style.textContent+="\n/* AUREL_LOGIN_AI_VIDEO_V8: show AI reconstructed pixels without faux-sharpen filters. */\n#aurel-auth-wall .auth-city-video{\n filter:none!important;opacity:1!important;transform:none!important;\n image-rendering:auto!important;\n}\n#aurel-auth-wall .auth-city-stage::before{\n background:linear-gradient(180deg,rgba(2,15,26,.19) 0%,rgba(4,18,30,.025) 36%,transparent 58%,rgba(2,16,26,.24) 100%)!important;\n}\n@media(max-width:960px){\n #aurel-auth-wall .auth-city-stage::before{\n  background:linear-gradient(90deg,rgba(3,24,36,.28) 0%,rgba(5,31,48,.045) 68%,transparent 100%)!important;\n }\n}\n";
